import math
def control(o):
    h=o['hitch_deg']; th=math.radians(-h)
    cam=o['views'].get('camera')
    e=0.0
    if cam:
        pts=[]
        for b,d in cam.get('walls',[]):
            a=math.radians(b)-th
            s=-d*math.cos(a); y=d*math.sin(a)
            if 1.5<s<6.5: pts.append((s,y))
        mids=[]
        for s in [2.5,3.5,4.5]:
            left=[p for p in pts if p[1]>0 and abs(p[0]-s)<0.8]
            right=[p for p in pts if p[1]<0 and abs(p[0]-s)<0.8]
            if left and right:
                l=min(left,key=lambda p:abs(p[0]-s)); r=min(right,key=lambda p:abs(p[0]-s))
                mids.append((l[1]+r[1])/2)
        if mids: e=sum(mids)/len(mids)
    desired=max(-28,min(28,math.degrees(math.atan(5.2*e/12.25))))
    steer=max(-34,min(34,0.75*h+2.0*(h-desired)))
    return steer,-0.8,-23

